function rewrite_links_scripts(country_code) {
    if (country_code == 'CN') {
        var strtr = {
            '//stackpath.bootstrapcdn.com/' : '//cdn.bootcss.com/twitter-',
            '//code.jquery.com/jquery-3.4.0' : '//cdn.bootcss.com/jquery/3.4.0/jquery',
            '//cdnjs.cloudflare.com/ajax/libs/' : '//cdn.bootcss.com/',
        };
        $('link').each(function(){
            var $initial = $(this).attr('href');
            for (var k in strtr) {
                $replace = $initial.replace(k, strtr[k]);
            }
            $(this).attr('href', $replace);
        });
        $('script').each(function(){
            var $initial = $(this).attr('src');
            for (var k in strtr) {
                $replace = $initial.replace(k, strtr[k]);
            }
            $(this).attr('src', $replace);
        });
    }
}
if (!document.cookie.split('; ').find(row.startsWith('_region='))) {
    $.getJSON('http://api.wipmania.com/jsonp?callback=?', function (data) {
        document.cookie = "_region=" + escape(data.address.country_code) + "; path=/";
        rewrite_links_scripts(data.address.country_code);
    });
} else {
    rewrite_links_scripts(document.cookie.split('; ').find(row => row.startsWith('_region=')).split('=')[1]);
}
